#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
public:
    int longestSubsequence(vector<int>& arr, int diff) {
        unordered_map<int, int> dp;
        int res = 0;
        for (int a : arr) {
            dp[a] = dp[a - diff] + 1;
            res = max(res, dp[a]);
        }
        return res;
    }
};
